{
  "description": "A standing chimeric creature shown in profile facing slightly to the right, combining the head, hindquarters, legs and tail of a red fox with the wings and chest plumage of a barn owl. The upper front is a fox head with reddish fur and a white muzzle, the mid-body and flanks are covered in creamy spotted owl feathers with two folded mottled wings, and the lower body and rear are fox-like with muscular hind legs and a long bushy tail with a white tip. The creature stands upright on two hind legs on a plain light background.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head at the top front, with reddish-orange fur on the forehead and cheeks, white fur on the muzzle, chin and throat, a black nose, amber eyes with dark pupils, and fine white whiskers",
      "where": "at the anterior top of the body, above the feathered chest"
    },
    {
      "part": "ears",
      "looks_like": "two large pointed upright fox ears with reddish outer fur, dark blackish rims and pale cream inner fur with dark interior shading",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short to medium reddish-brown fur above fading to darker gray-brown on the lower shin, bent at the hock in a digitigrade stance",
      "where": "under the mid and rear body, extending down to the ground"
    },
    {
      "part": "feet",
      "looks_like": "two paw-like feet with dark pads and short blunt claws, covered in short dark brown fur on top",
      "where": "at the bottom ends of the two hind legs, resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "one long thick bushy tail covered in long reddish-brown fur with darker underfur and a distinct white tip at the end",
      "where": "extending from the rear of the body, angled down and outward behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two folded wings with layered flight feathers in tan, cream, pale gray and brown, with dark speckling and barring on the coverts and primaries",
      "where": "along the left and right sides of the torso, from the shoulder mid-body to the lower flank"
    },
    {
      "part": "feathers",
      "looks_like": "dense soft owl-like plumage on the chest, belly and wings; chest and belly are creamy-white and fluffy, wing feathers are mottled gray, tan and white",
      "where": "covering the throat, chest, belly and the entire wing surfaces"
    },
    {
      "part": "markings",
      "looks_like": "small scattered dark brown to black spots and dots, denser on the throat and chest and sparser on the wing coverts, with darker barring on the flight feathers",
      "where": "across the creamy chest, throat, belly and on the tan and gray wing feathers"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
